// useHodReview.ts  — DEBUG VERSION
// Full console logging at every step to trace "No jobs found" issue.
// ✅ Remove all console.group / console.log lines once data is confirmed working.

import { useState, useEffect, useCallback } from "react";
import { hodReviewService } from "../services/EvaluationApiService";
import { HodMessages, WorkflowAction, workflowStatusApi } from "../config/EvaluationConfig";
import {
  StatusId,
} from "../../../../utilities/Config";
import type {
  ReviewScorecardJob,
  ReviewScorecardCandidate,
} from "../services/IEvaluationService";

export type HodDecision = "select" | "reject" | "hold" | null;

const HOD_ACTION: Record<"select" | "reject" | "hold", number> = {
  select: WorkflowAction.Approved,  // 1
  reject: WorkflowAction.Reject,    // 2
  hold:   WorkflowAction.OnHold,    // 10
};

const HOD_WORKFLOW: Record<"select" | "reject" | "hold", string> = {
  select: workflowStatusApi.CandidateSelectedIPanel,  // "WS06"
  reject: workflowStatusApi.CandidateRejectedIPanel,  // "WS08"
  hold:   workflowStatusApi.CandidateOnHoldIPanel,    // "WS07"
};

const HOD_MSG: Record<"select" | "reject" | "hold", string> = {
  select: HodMessages.CandidateSelected,
  reject: HodMessages.CandidateRejected,
  hold:   HodMessages.CandidateOnHold,
};

const ON_HOLD_IDS: number[] = [
  StatusId.OnHoldbyHOD,                // 123
  StatusId.CandidateOnHoldbyHODLevel1, // 165
  StatusId.CandidateOnHoldbyHODLevel2, // 166
];

const REJECTED_IDS: number[] = [
  StatusId.RejectedbyHOD,                // 15
  StatusId.CandidateRejectedbyHODLevel1, // 167
  StatusId.CandidateRejectedbyHODLevel2, // 168
];

const LEVEL2_IDS: number[] = [
  StatusId.PendingwithHODtoselectthecandidateLevel2, // 127
  StatusId.CandidateOnHoldbyHODLevel2,               // 166
];

function resolveDecision(statusId: number): HodDecision {
  if (statusId === StatusId.Selected)  return "select"; // 122
  if (ON_HOLD_IDS.includes(statusId))  return "hold";
  if (REJECTED_IDS.includes(statusId)) return "reject";
  return null;
}

// =============================================================================
//  useReviewScorecard — with full debug logging
// =============================================================================
export function useReviewScorecard(
  roleIDs:      number[],
  employeeList: any[],
  hodEmail:     string,
  onFormOpen?:  (open: boolean) => void
) {
  const [jobs,              setJobs]             = useState<ReviewScorecardJob[]>([]);
  const [jobsLoading,       setJobsLoading]      = useState(true);
  const [drawerOpen,        setDrawerOpen]       = useState(false);
  const [selectedJob,       setSelectedJob]      = useState<ReviewScorecardJob | null>(null);
  const [candidates,        setCandidates]       = useState<ReviewScorecardCandidate[]>([]);
  const [candidatesLoading, setCandidatesLoading]= useState(false);
  const [modalOpen,         setModalOpen]        = useState(false);
  const [selectedCandidate, setSelectedCandidate]= useState<ReviewScorecardCandidate | null>(null);
  const [decision,      setDecisionState] = useState<HodDecision>(null);
  const [comments,      setCommentsState] = useState("");
  const [commentsError, setCommentsError] = useState(false);
  const [decisionError, setDecisionError] = useState(false);
  const [submitting,    setSubmitting]    = useState(false);
  const [alertMsg,      setAlertMsg]      = useState("");
  const [alertType,     setAlertType]     = useState<"success" | "error" | "">("");

  // ── Load jobs ────────────────────────────────────────────────────────────────
  useEffect(() => {

    // ─────────────────────────────────────────────────────────────────────────
    // DEBUG BLOCK 1 — Check hodEmail received from ADGroupData
    // Open Browser DevTools → Console to see these logs
    // ─────────────────────────────────────────────────────────────────────────
    console.group("🔍 [ReviewScorecard] useEffect - hodEmail check");
    console.log("hodEmail value   :", hodEmail);
    console.log("hodEmail type    :", typeof hodEmail);
    console.log("hodEmail length  :", hodEmail?.length ?? 0);
    console.log("hodEmail empty?  :", !hodEmail);
    console.log("roleIDs          :", roleIDs);
    console.log("employeeList len :", employeeList?.length ?? 0);
    console.groupEnd();
    // ─────────────────────────────────────────────────────────────────────────

    if (!hodEmail) {
      console.warn(
        "⚠️ [ReviewScorecard] hodEmail is EMPTY — fetch skipped.\n" +
        "   Fix: Check ADGroupData?.EmailId?.[0] in ReviewScorecardTab.tsx\n" +
        "   The RoleContext must return an EmailId array with the HOD email."
      );
      setJobs([]);
      setJobsLoading(false);
      return;
    }

    let cancelled = false;
    (async () => {
      setJobsLoading(true);

      // ───────────────────────────────────────────────────────────────────────
      // DEBUG BLOCK 2 — SP query being sent
      // ───────────────────────────────────────────────────────────────────────
      console.group("📡 [ReviewScorecard] Calling fetchReviewScorecardJobs");
      console.log("List    : HRMSRecruitmentDptDetails");
      console.log("Filter  : StatusId = 28 (RecruitmentInProgress)");
      console.log("Filter  : HOD =", hodEmail);
      console.log("⚠️  Make sure the HOD column in HRMSRecruitmentDptDetails stores EMAIL, not a name/ID");
      console.groupEnd();
      // ───────────────────────────────────────────────────────────────────────

      const result = await hodReviewService.fetchReviewScorecardJobs(hodEmail);

      // ───────────────────────────────────────────────────────────────────────
      // DEBUG BLOCK 3 — SP response
      // ───────────────────────────────────────────────────────────────────────
      console.group("📦 [ReviewScorecard] fetchReviewScorecardJobs result");
      console.log("Jobs count :", result.length);

      if (result.length === 0) {
        console.warn("❌ ZERO jobs returned. Check these:");
        console.warn("   REASON 1 → HOD column value in SP does NOT match email:", hodEmail);
        console.warn("              Open HRMSRecruitmentDptDetails in SP and check the HOD column value for a known record");
        console.warn("   REASON 2 → No records have StatusId = 28 for this HOD");
        console.warn("              Try removing the StatusId filter temporarily to confirm records exist");
        console.warn("   REASON 3 → ADGroupData.EmailId[0] is undefined/null");
        console.warn("              Log ADGroupData from useRoleContext() in the component");
      } else {
        console.log("✅ Jobs returned:");
        console.table(result.map((j: ReviewScorecardJob) => ({
          id:               j.id,
          jobCode:          j.jobCode,
          jobTitle:         j.jobTitle,
          statusId:         j.statusId,
          status:           j.status,
          nationality:      j.nationality,
          businessUnitCode: j.businessUnitCode,
        })));
      }
      console.groupEnd();
      // ───────────────────────────────────────────────────────────────────────

      if (!cancelled) {
        setJobs(result);
        setJobsLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [hodEmail]);

  // ── Open candidate drawer ────────────────────────────────────────────────────
  const openDrawer = useCallback(async (job: ReviewScorecardJob) => {
    setSelectedJob(job);
    setDrawerOpen(true);
    setCandidatesLoading(true);

    // ─────────────────────────────────────────────────────────────────────────
    // DEBUG BLOCK 4 — Candidate fetch params
    // ─────────────────────────────────────────────────────────────────────────
    console.group("📡 [ReviewScorecard] Calling fetchCandidatesForJob");
    console.log("recruitmentID (job.id) :", job.id);
    console.log("jobCodeId              :", (job as any).jobCodeId ?? 0);
    console.log("employeeList length    :", employeeList?.length ?? 0);
    console.log("Filter StatusId IN     : [121,122,123,15,130,127,165,166,167,168]");
    console.log("Filter ItemCreated     : No");
    console.groupEnd();
    // ─────────────────────────────────────────────────────────────────────────

    const result = await hodReviewService.fetchCandidatesForJob(
      job.id,
      (job as any).jobCodeId ?? 0,
      employeeList
    );

    // ─────────────────────────────────────────────────────────────────────────
    // DEBUG BLOCK 5 — Candidates result
    // ─────────────────────────────────────────────────────────────────────────
    console.group("📦 [ReviewScorecard] fetchCandidatesForJob result");
    console.log("Candidates count :", result.length);
    if (result.length === 0) {
      console.warn("❌ ZERO candidates returned. Check these:");
      console.warn("   REASON 1 → All candidates for this job have ItemCreated = 'Yes' (already processed)");
      console.warn("   REASON 2 → No candidates have HOD-relevant StatusId");
      console.warn("   REASON 3 → jobCodeId mismatch — job.jobCodeId was:", (job as any).jobCodeId);
    } else {
      console.table(result.map((c: ReviewScorecardCandidate) => ({
        id:           c.id,
        name:         c.applicantName,
        statusId:     c.statusId,
        status:       c.status,
        recruitmentID:c.recruitmentID,
        gpa:          c.gpa,
        grade:        c.grade,
      })));
    }
    console.groupEnd();
    // ─────────────────────────────────────────────────────────────────────────

    setCandidates(result);
    setCandidatesLoading(false);
  }, [employeeList]);

  const closeDrawer = useCallback(() => {
    setDrawerOpen(false); setSelectedJob(null); setCandidates([]);
  }, []);

  const openModal = useCallback((candidate: ReviewScorecardCandidate) => {
    setSelectedCandidate(candidate);
    setDecisionState(resolveDecision(candidate.statusId));
    setCommentsState(""); setCommentsError(false); setDecisionError(false);
    setAlertMsg(""); setAlertType("");
    setModalOpen(true);
    onFormOpen?.(true);
  }, [onFormOpen]);

  const closeModal = useCallback(() => {
    setModalOpen(false); setSelectedCandidate(null);
    onFormOpen?.(false);
  }, [onFormOpen]);

  const handleSetDecision = useCallback((d: HodDecision) => {
    setDecisionState(d); setDecisionError(false);
  }, []);

  const handleSetComments = useCallback((v: string) => {
    setCommentsState(v); if (v.trim()) setCommentsError(false);
  }, []);

  const handleHodSubmit = useCallback(async () => {
    if (!decision)          { setDecisionError(true); return; }
    if (!comments.trim())   { setCommentsError(true); return; }
    if (!selectedCandidate) return;

    setSubmitting(true);

    const isLevel2     = LEVEL2_IDS.includes(selectedCandidate.statusId);
    const gpa          = (selectedCandidate as any).gpaRaw ?? selectedCandidate.gpa;
    const jobRequestID = (selectedCandidate as any).jobRequestID ?? "";

    // ─────────────────────────────────────────────────────────────────────────
    // DEBUG BLOCK 6 — Submit payload
    // ─────────────────────────────────────────────────────────────────────────
    console.group("📤 [ReviewScorecard] submitHodDecision payload");
    console.log("candidateId    :", selectedCandidate.id);
    console.log("decision       :", decision);
    console.log("actionId       :", HOD_ACTION[decision]);
    console.log("workflowStatus :", HOD_WORKFLOW[decision]);
    console.log("isLevel2       :", isLevel2);
    console.log("gpa            :", gpa);
    console.log("jobRequestID   :", jobRequestID);
    console.groupEnd();
    // ─────────────────────────────────────────────────────────────────────────

    const result = await hodReviewService.submitHodDecision({
      candidateId: selectedCandidate.id,
      actionId:    HOD_ACTION[decision],
      comments, isLevel2, jobRequestID, gpa,
      workflowStatus:    HOD_WORKFLOW[decision],
      othersInterviewed: "No",
    });

    console.log("📬 [ReviewScorecard] submitHodDecision result:", result);

    setSubmitting(false);

    if (result.success) {
      setAlertMsg(HOD_MSG[decision]); setAlertType("success");
      setTimeout(() => {
        closeModal();
        if (selectedJob) openDrawer(selectedJob);
      }, 1600);
    } else {
      setAlertMsg(result.message); setAlertType("error");
    }
  }, [decision, comments, selectedCandidate, selectedJob, closeModal, openDrawer]);

  return {
    jobs, jobsLoading,
    drawerOpen, selectedJob, candidates, candidatesLoading,
    openDrawer, closeDrawer,
    modalOpen, selectedCandidate, openModal, closeModal,
    decision, handleSetDecision,
    comments, handleSetComments,
    commentsError, decisionError,
    submitting, alertMsg, alertType,
    hideAlert:      () => { setAlertMsg(""); setAlertType(""); },
    handleHodSubmit,
  };
}

// =============================================================================
//  useHodReview — standalone candidate view
// =============================================================================
export function useHodReview(
  candidateId:  number,
  employeeList: any[],
  onBack:       () => void
) {
  const [decision,      setDecisionState] = useState<HodDecision>(null);
  const [comments,      setCommentsState] = useState("");
  const [commentsError, setCommentsError] = useState(false);
  const [decisionError, setDecisionError] = useState(false);
  const [submitting,    setSubmitting]    = useState(false);
  const [alertMsg,      setAlertMsg]      = useState("");
  const [alertType,     setAlertType]     = useState<"success" | "error" | "">("");
  const [statusId,      setStatusId]      = useState(0);
  const [jobRequestID,  setJobRequestID]  = useState("");
  const [gpa,           setGpa]           = useState<number | string>("");

  const loadFromCandidate = useCallback((candidate: ReviewScorecardCandidate) => {
    console.group("🔍 [useHodReview] loadFromCandidate");
    console.log("candidateId  :", candidate.id);
    console.log("statusId     :", candidate.statusId);
    console.log("gpa          :", candidate.gpa);
    console.log("jobRequestID :", (candidate as any).jobRequestID);
    console.groupEnd();
    const st = candidate.statusId;
    setStatusId(st);
    setJobRequestID((candidate as any).jobRequestID ?? "");
    setGpa((candidate as any).gpaRaw ?? candidate.gpa);
    setDecisionState(resolveDecision(st));
    setCommentsState(""); setCommentsError(false); setDecisionError(false);
    setAlertMsg(""); setAlertType("");
  }, []);

  const handleSetDecision = useCallback((d: HodDecision) => {
    setDecisionState(d); setDecisionError(false);
  }, []);

  const handleSetComments = useCallback((v: string) => {
    setCommentsState(v); if (v.trim()) setCommentsError(false);
  }, []);

  const handleSubmit = useCallback(async () => {
    if (!decision)        { setDecisionError(true); return; }
    if (!comments.trim()) { setCommentsError(true); return; }
    setSubmitting(true);
    const result = await hodReviewService.submitHodDecision({
      candidateId,
      actionId:          HOD_ACTION[decision],
      comments,
      isLevel2:          LEVEL2_IDS.includes(statusId),
      jobRequestID, gpa,
      workflowStatus:    HOD_WORKFLOW[decision],
      othersInterviewed: "No",
    });
    setSubmitting(false);
    if (result.success) {
      setAlertMsg(HOD_MSG[decision]); setAlertType("success");
      setTimeout(onBack, 1600);
    } else {
      setAlertMsg(result.message); setAlertType("error");
    }
  }, [decision, comments, statusId, candidateId, jobRequestID, gpa, onBack]);

  return {
    decision, handleSetDecision,
    comments, handleSetComments,
    commentsError, decisionError,
    submitting, alertMsg, alertType,
    loadFromCandidate, handleSubmit,
    hideAlert: () => { setAlertMsg(""); setAlertType(""); },
  };
}